// This file is an unsanitized copy of the repo owner's own real hotkeys.js, refreshed
// automatically by dev-scripts/make-template.sh on every commit (see hooks/pre-commit) —
// a real, working example instead of generic placeholders. hotkeys.js itself stays
// gitignored (a `git pull` never touches your own local edits to it); copy this file to
// hotkeys.js and edit it to match your own setup. See linux/README.md and the porting
// checklist for what each binding type does.

// Generated by the AltTabSucks hotkeys UI (shared/hotkeys-ui.html) from hotkeys.json.
// Hand edits here will be overwritten the next time you save in the UI — edit
// hotkeys.json (or just use the UI) instead, unless you never use the UI at all.


registerShortcut("Hotkey config", "AltTabSucks: Hotkey config",
    "Ctrl+Alt+/", function () { focusTab("brave-browser", "Personal", ["localhost:9876/hotkeys-ui"], "http://localhost:9876/hotkeys-ui"); });

